const slugify = (value) =>
  value
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");

const palette = [
  "from-blue-950 via-indigo-900 to-slate-950",
  "from-emerald-950 via-teal-900 to-slate-950",
  "from-violet-950 via-purple-900 to-slate-950",
  "from-amber-900 via-orange-900 to-slate-950",
  "from-cyan-950 via-sky-900 to-slate-950",
  "from-rose-950 via-red-900 to-slate-950",
  "from-fuchsia-950 via-purple-900 to-slate-950",
  "from-slate-950 via-blue-950 to-black",
];

function createLesson(course, module, raw, lessonIndex) {
  const lessonNumber = lessonIndex + 1;
  const projectLesson = lessonNumber === 8;
  const title = raw.title;
  const focus = raw.focus;

  return {
    id: `${course.id}-m${module.id}-l${lessonNumber}`,
    courseId: course.id,
    courseTitle: course.title,
    moduleNumber: module.id,
    moduleTitle: module.title,
    lessonNumber,
    slug: raw.slug || slugify(title),
    title,
    subtitle: raw.subtitle || focus,
    duration: projectLesson ? "75–120 minutes" : "45–60 minutes",
    level: module.level || course.level,
    status: "Available",
    essentialQuestion: raw.question || `How does ${title} help us build a correct, dependable solution?`,
    bigIdea: raw.bigIdea || `${focus} Professional work combines clear reasoning, readable implementation, testing, and explanation.`,
    whyItMatters: raw.why || `${title} is a practical building block in ${course.title.toLowerCase()}. Learners must be able to explain the idea, implement it, test it, and recognize when a different approach is better.`,
    objectives: [
      `Explain the purpose of ${title}.`,
      `Use the lesson concept in a working example.`,
      "Trace the result and verify it with a test or inspection.",
      "Recognize common errors and correct them systematically.",
      "Connect the technique to a realistic application or portfolio artifact.",
    ],
    vocabulary: module.vocabulary,
    keyReference: module.keyReference,
    visualSteps: [
      { label: "1. Define", detail: `State the problem that ${title} will solve.` },
      { label: "2. Model", detail: "Identify inputs, outputs, rules, states, and constraints." },
      { label: "3. Build", detail: `Implement the smallest correct ${module.artifactLabel}.` },
      { label: "4. Test", detail: "Check normal cases, boundaries, invalid input, and failure behavior." },
      { label: "5. Explain", detail: "Document decisions, evidence, limitations, and next improvements." },
    ],
    workedExamples: [
      {
        title: `Core example — ${title}`,
        code: raw.code,
        explanation: raw.explanation || `This example demonstrates ${focus.toLowerCase()} with a small result that can be inspected and tested.`,
      },
      {
        title: "Trace and predict",
        code: raw.trace || raw.code,
        explanation: "Predict the output before running the example. Then trace each important value or browser/database state and explain any difference.",
      },
      {
        title: "Professional extension",
        code: raw.extension || raw.code,
        explanation: "Extend the example with validation, clearer naming, one edge case, and a test or verification query.",
      },
    ],
    lab: {
      title: raw.lab || `Build and verify: ${title}`,
      instructions: [
        "Create the smallest working version from an empty file or database.",
        "Run or render the artifact and preserve the result.",
        "Test one normal case, one boundary case, and one invalid case.",
        "Correct every error instead of hiding or bypassing it.",
        "Add comments or a README explaining the design and evidence.",
      ],
      deliverables: [
        `A working ${module.artifactLabel}`,
        "A test or verification record",
        "A short explanation of decisions and limitations",
        "One justified improvement",
      ],
    },
    guidedPractice: [
      `Define ${title} in your own words.`,
      `Identify the inputs and outputs in the core example.`,
      "Trace the example one step at a time and predict the result.",
      "Change one value or rule and explain what changes.",
      "Find or create one error, then document the correction.",
    ],
    independentPractice: [
      `Create a new example using the ${title} concept.`,
      "Add input validation or constraint checking.",
      "Test three cases and record expected versus actual results.",
      "Refactor the solution for clarity and reuse.",
      `Apply the lesson to ${module.project}.`,
    ],
    commonMistakes: module.commonMistakes,
    project: projectLesson
      ? {
          title: module.project,
          description: module.projectDescription,
          requirements: [
            "A clear user or decision problem",
            "A working implementation using the module skills",
            "Validation, edge cases, and failure handling",
            "Readable structure and documentation",
            "Screenshots or output evidence",
            "A reflection describing limitations and next steps",
          ],
        }
      : null,
    assessment: Array.from({ length: 10 }, (_, index) => ({
      id: `${course.id}-m${module.id}-l${lessonNumber}-q${index + 1}`,
      points: 10,
      prompt:
        index < 5
          ? [
              `Explain ${title} and its purpose.`,
              "Interpret the core example and predict its result.",
              "Identify an assumption or constraint in the example.",
              "Correct a likely error and explain the correction.",
              "Describe how the result should be verified.",
            ][index]
          : [
              "Create a valid application of the lesson concept.",
              "Test a boundary case and report the evidence.",
              "Compare this approach with one alternative.",
              "Explain a security, accessibility, privacy, or reliability concern.",
              "Defend whether the artifact is ready to include in a portfolio.",
            ][index - 5],
    })),
    summary: [
      focus,
      "Correctness must be demonstrated with visible evidence.",
      "Readable structure, testing, and documentation are part of the solution.",
      "A portfolio artifact should communicate both capability and limitations.",
    ],
    reflection: [
      "What can you now build that you could not build before?",
      "Which error taught you the most?",
      "How did you verify that your result was correct?",
      "What would you improve before showing this work to an employer?",
    ],
  };
}

function createModule(course, raw, index) {
  const module = {
    id: index + 1,
    title: raw.title,
    description: raw.description,
    duration: raw.duration || "8–12 hours",
    level: raw.level || course.level,
    color: palette[index],
    objectives: raw.objectives,
    vocabulary: raw.vocabulary.map(([term, definition]) => ({ term, definition })),
    keyReference: raw.keyReference,
    artifactLabel: raw.artifactLabel,
    project: raw.project,
    projectDescription: raw.projectDescription,
    commonMistakes: raw.commonMistakes,
  };

  module.lessons = raw.lessons.map((lesson, lessonIndex) =>
    createLesson(course, module, lesson, lessonIndex)
  );

  return module;
}

function createCourse(raw) {
  const course = {
    ...raw,
    moduleCount: 8,
    lessonCount: 64,
    projectCount: 8,
  };
  course.modules = raw.modules.map((module, index) =>
    createModule(course, module, index)
  );
  return course;
}

