export const computerScienceCourses = rawCourses.map(createCourse);

export function getComputerScienceCourse(courseSlug) {
  return computerScienceCourses.find(
    (course) => course.slug === courseSlug || course.id === courseSlug
  );
}

export function getComputerScienceModule(courseSlug, moduleNumber) {
  return getComputerScienceCourse(courseSlug)?.modules.find(
    (module) => module.id === Number(moduleNumber)
  );
}

export function getComputerScienceLesson(courseSlug, moduleNumber, lessonSlug) {
  return getComputerScienceModule(courseSlug, moduleNumber)?.lessons.find(
    (lesson) => lesson.slug === lessonSlug
  );
}

export function getCourseLessonPath(course, lesson) {
  return `${course.basePath}/module/${lesson.moduleNumber}/lesson/${lesson.slug}`;
}

export function getAllCourseLessons(course) {
  return course?.modules.flatMap((module) => module.lessons) || [];
}

